/* eslint-env node */
/* eslint-disable @typescript-eslint/no-var-requires */
const { chromium } = require('playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs');
async function main() {
  const { createServer } = await import('vite');
  const server = await createServer({ server: { host: '127.0.0.1', port: 4292, strictPort: true } });
  await server.listen();
  let browser;
  try {
    browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_EXECUTABLE_PATH || undefined, args: ['--no-sandbox'] });
    const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, reducedMotion: 'reduce' });
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    const go = async section => {
      await page.goto('http://127.0.0.1:4292/#/app/settings/' + section);
      await page.getByTestId('settings-title').waitFor();
    };
    await go('business');
    const sidebar = page.locator('[data-settings-directory]');
    assert.equal(await sidebar.isVisible(), true, 'Settings directory is embedded in normal ERP workspace');
    assert.equal(await page.locator('[data-sidebar="sidebar"]').isVisible(), true, 'Normal ERP navigation remains visible');
    const sub = page.getByRole('tablist',{name:'Business profile sub-settings'});
    await page.getByLabel('Business name', { exact: true }).fill('Library draft shop');
    await sidebar.getByRole('searchbox').fill('Business');
    assert.equal(await sidebar.getByRole('tab').count(),1);
    await sidebar.getByRole('searchbox').fill('no-such-setting');
    await sidebar.getByText('No matching sections.', { exact: true }).waitFor();
    await sidebar.getByRole('searchbox').fill('');
    await sub.getByRole('tab', { name: /Contact & address/ }).click();
    await page.getByLabel('Phone number', { exact: true }).fill('01711000245');
    await sub.getByRole('tab', { name: /General/ }).click();
    assert.equal(await page.getByLabel('Business name', { exact: true }).inputValue(), 'Library draft shop');
    assert.equal(Math.round((await sidebar.boundingBox()).width), 280);
    await page.getByRole('button', { name: 'Save changes', exact: true }).click();
    await page.getByRole('status').filter({ hasText: 'Business settings saved.' }).waitFor();
    await go('team');
    await page.getByRole('button', { name: 'Edit employee Mahmud Hasan', exact: true }).click();
    const editor = page.getByRole('dialog', { name: 'Edit employee', exact: true });
    await editor.getByRole('button', { name: /^Joined date:/ }).click();
    await page.locator('[data-calendar-date][aria-current="date"]').first().click();
    await page.getByRole('button', { name: 'Apply', exact: true }).click();
    await editor.getByRole('button', { name: 'Keep employee draft', exact: true }).click();
    await page.getByRole('button', { name: 'Save changes', exact: true }).click();
    await page.getByRole('status').filter({ hasText: 'Business settings saved.' }).waitFor();
    const table = page.getByRole('region', { name: 'Employees table', exact: true });
    const search = page.getByRole('searchbox', { name: 'Search employees', exact: true });
    await page.getByRole('button', { name: /^Employee joined date range:/ }).click();
    await page.getByRole('button', { name: 'Today', exact: true }).click();
    await page.getByRole('button', { name: 'Apply', exact: true }).click();
    await table.getByText('Mahmud Hasan', { exact: true }).waitFor();
    assert.equal(await table.getByText('Rafiq Islam', { exact: true }).count(), 0, 'Unknown joined dates never match a bounded period');
    await page.getByRole('button', { name: 'Clear employee filters', exact: true }).click();
    await search.fill('accountant');
    await table.getByText('Rafiq Islam', { exact: true }).waitFor();
    assert.equal(await table.getByText('Mahmud Hasan', { exact: true }).count(), 0);
    await search.fill('no-such-person');
    await table.getByText('No matching employees.', { exact: true }).waitFor();
    await page.getByRole('button', { name: 'Clear employee filters', exact: true }).click();
    await page.getByRole('button', { name: /^Filters/ }).click();
    await page.getByRole('combobox', { name: 'Employee status', exact: true }).click();
    await page.locator('[role=option][data-value=disabled]').click();
    await table.getByText('No matching employees.', { exact: true }).waitFor();
    await page.getByRole('button', { name: 'Clear employee filters', exact: true }).click();
    await page.getByRole('button', { name: 'Columns', exact: true }).click();
    const columns = page.getByRole('dialog', { name: 'Employee columns', exact: true });
    assert.equal(await columns.getByRole('checkbox', { name: 'Employee', exact: true }).isDisabled(), true);
    await columns.getByRole('checkbox', { name: 'Roles', exact: true }).uncheck();
    await columns.getByRole('button', { name: 'Done', exact: true }).click();
    assert.equal(await table.getByRole('columnheader', { name: 'Roles', exact: true }).count(), 0);
    assert.equal(await page.getByRole('button', { name: 'Save changes', exact: true }).isDisabled(), true, 'View controls never dirty business settings');
    await page.reload();
    await table.waitFor();
    assert.equal(await table.getByRole('columnheader', { name: 'Roles', exact: true }).count(), 0);
    await page.getByRole('button', { name: 'Columns', exact: true }).click();
    await columns.getByRole('button', { name: 'Reset columns', exact: true }).click();
    await columns.getByRole('button', { name: 'Done', exact: true }).click();
    await table.getByRole('columnheader', { name: 'Roles', exact: true }).waitFor();
    for (const width of [390, 768, 800, 1024, 1440]) {
      await page.setViewportSize({ width, height: 1000 });
      await page.waitForFunction(() => document.querySelector('[aria-label="Employee settings views"]').getAttribute('aria-orientation') === 'horizontal');
      assert.equal(await page.locator('[data-settings-directory]').isVisible(), width >= 1024, 'Only desktop shows Settings sidebar');
      assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth + 1), false, 'Employee page fits at ' + width);
    }
    fs.mkdirSync('.superpowers/sdd/settings-report-library/screens', { recursive: true });
    for (const theme of ['light', 'dark']) {
      await page.emulateMedia({ colorScheme: theme });
      await page.evaluate(theme => document.documentElement.setAttribute('data-theme', theme), theme);
      for (const width of [390, 768, 1440]) {
        await page.setViewportSize({ width, height: 1000 });
        await page.screenshot({ path: `.superpowers/sdd/settings-report-library/screens/team-${width}-${theme}.png`, fullPage: true });
      }
    }
    await go('data');
    await page.setViewportSize({ width: 1440, height: 1000 });
    const directoryRect = await page.locator('[data-settings-directory]').boundingBox();
    const contentRect = await page.locator('[data-settings-subpanel]').boundingBox();
    assert.ok(directoryRect && contentRect && Math.abs(directoryRect.y - contentRect.y) <= 2,
      'Desktop Settings content starts level with the in-page Party-style directory (no hidden-tab top gap)');
    const activity = page.getByRole('region', { name: 'Settings activity', exact: true });
    await activity.getByRole('searchbox', { name: 'Search settings activity', exact: true }).fill('no-such-change');
    await activity.getByText('No matching activity.', { exact: true }).waitFor();
    await activity.getByRole('button', { name: 'Clear activity filters', exact: true }).click();
    assert.ok(await activity.getByRole('cell', { name: 'Business profile', exact: true }).count());
    await activity.getByRole('button', { name: /^Settings activity date range:/ }).click();
    await page.getByRole('button', { name: 'Yesterday', exact: true }).click();
    await page.getByRole('button', { name: 'Apply', exact: true }).click();
    await activity.getByText('No matching activity.', { exact: true }).waitFor();
    await activity.getByRole('button', { name: 'Clear activity filters', exact: true }).click();
    assert.ok(await activity.getByRole('cell', { name: 'Business profile', exact: true }).count());
    await page.setViewportSize({ width: 1440, height: 1000 });
    const secret = 'HisabIQ browser recovery key 123';
    await page.getByLabel('HisabIQ secret key', { exact: true }).fill(secret);
    await page.getByLabel('Confirm secret key for download', { exact: true }).fill(secret);
    const downloaded = page.waitForEvent('download');
    await page.getByRole('button', { name: 'Download encrypted SQL', exact: true }).click();
    const file = await downloaded;
    const backupPath = '.superpowers/sdd/settings-report-library/backup.sql.hiq';
    await file.saveAs(backupPath);
    assert.equal(await page.getByLabel('HisabIQ secret key', { exact: true }).inputValue(), '');
    assert.ok(!fs.readFileSync(backupPath, 'utf8').includes('Library draft shop'));
    await go('business');
    await page.getByLabel('Business name', { exact: true }).fill('Changed after SQL backup');
    await page.getByRole('button', { name: 'Save changes', exact: true }).click();
    await page.getByRole('status').filter({ hasText: 'Business settings saved.' }).waitFor();
    await go('data');
    await page.getByLabel('HisabIQ secret key', { exact: true }).fill('incorrect recovery key');
    await page.getByLabel('Choose SQL backup to restore', { exact: true }).setInputFiles(backupPath);
    await page.getByRole('button', { name: 'Review SQL restore', exact: true }).click();
    await page.getByRole('alert').filter({ hasText: /key is incorrect or the backup is damaged/ }).waitFor();
    await page.getByLabel('HisabIQ secret key', { exact: true }).fill(secret);
    await page.getByRole('button', { name: 'Review SQL restore', exact: true }).click();
    const review = page.getByRole('dialog', { name: 'Review settings restore', exact: true });
    await review.waitFor();
    assert.ok(await review.getByText('Business profile', { exact: true }).count());
    await review.getByRole('button', { name: 'Restore settings', exact: true }).click();
    await page.getByRole('status').filter({ hasText: 'Business settings restored.' }).waitFor();
    await go('business');
    assert.equal(await page.getByLabel('Business name', { exact: true }).inputValue(), 'Library draft shop');
    await page.goto('http://127.0.0.1:4292/#/app/reports?screen=library&report=sales-register&from=&to=');
    await page.getByRole('searchbox', { name: 'Search report records', exact: true }).waitFor();
    await page.getByRole('searchbox', { name: 'Find a report', exact: true }).fill('Stock');
    await page.locator('[data-workspace-library]').getByRole('button', { name: /Stock/ }).first().waitFor();
    await page.getByRole('searchbox', { name: 'Find a report', exact: true }).fill('');
    const originalRows = await page.locator('[data-report-row]').count();
    assert.ok(originalRows > 0);
    await page.getByRole('searchbox', { name: 'Search report records', exact: true }).fill('no-such-report-record');
    await page.getByText('No records match your filters.', { exact: true }).waitFor();
    await page.getByRole('button', { name: 'Clear filters', exact: true }).click();
    assert.equal(await page.locator('[data-report-row]').count(), originalRows);
    await page.getByRole('button', { name: 'Columns', exact: true }).click();
    await page.getByRole('dialog', { name: 'Visible columns', exact: true }).getByRole('checkbox', { name: 'Paid', exact: true }).uncheck();
    await page.getByRole('button', { name: 'Done', exact: true }).click();
    assert.equal(await page.getByRole('columnheader', { name: 'Paid', exact: true }).count(), 0);
    assert.deepEqual(errors, []);
    console.log('Shared Reports library/search, navigation filtering, draft preservation, employee filters/columns, activity date range, encrypted SQL download/wrong-key/review/restore, unchanged Reports search/columns, five widths and six screenshots passed.');
  } finally { await browser?.close(); await server.close(); }
}
main().catch(e => { console.error(e); process.exitCode = 1; });
